/**
 * iSchool — Lightbase Collection Schema Setup
 *
 * Recreates all collections with flexible schemas that work with
 * Lightbase's auto-generated string IDs. The original collections
 * enforced `school_id` as integer, but Lightbase generates string IDs
 * like "g7jr4nbx9rnmzs20cfk1kawxvr" for documents, so we use string
 * type for all foreign key references.
 *
 * Usage:
 *   node --experimental-strip-types scripts/setup-lightbase-collections.ts
 */

const API_KEY = process.env.LIGHTBASE_API_KEY || '';
const PROJECT = process.env.LIGHTBASE_PROJECT || 'ischool-beta';
const BASE_URL = process.env.LIGHTBASE_BASE_URL || '';

if (!API_KEY || !BASE_URL) {
  console.error('ERROR: LIGHTBASE_API_KEY and LIGHTBASE_BASE_URL environment variables are required.');
  process.exit(1);
}

const HEADERS: Record<string, string> = {
  'apikey': API_KEY,
  'x-lightbase-project': PROJECT,
  'Content-Type': 'application/json',
};
const COLL_URL = `${BASE_URL}/api/v1/projects/${PROJECT}/collections`;

async function listCollections(): Promise<Set<string>> {
  const res = await fetch(COLL_URL, { headers: HEADERS });
  if (!res.ok) throw new Error(`listCollections failed: ${res.status}`);
  const data = await res.json();
  const arr = data.collections || [];
  return new Set(arr.map((c: any) => c.name));
}

async function deleteCollection(name: string): Promise<void> {
  const res = await fetch(`${COLL_URL}/${name}`, {
    method: 'DELETE',
    headers: HEADERS,
  });
  if (res.ok) console.log(`  [deleted] ${name}`);
  else console.log(`  [skip-delete] ${name} (${res.status})`);
}

async function createCollection(name: string, fields: any[]): Promise<void> {
  const res = await fetch(COLL_URL, {
    method: 'POST',
    headers: HEADERS,
    body: JSON.stringify({ name, fields }),
  });
  if (res.ok) {
    console.log(`  [created] ${name}`);
    return;
  }
  const err = await res.json().catch(() => ({}));
  const msg = err.error?.message || '';
  if (msg.includes('already exists')) {
    console.log(`  [exists]  ${name}`);
    return;
  }
  console.warn(`  [fail]    ${name}: ${res.status} ${msg.substring(0, 100)}`);
}

// Field type shortcuts — Lightbase requires unique fields to be indexed
const f = {
  str: (name: string, required = false, unique = false, def?: string) => ({
    name, type: 'string', required, unique, indexed: unique || false,
    ...(def !== undefined ? { default: def } : {}),
  }),
  text: (name: string, required = false) => ({ name, type: 'text', required }),
  int: (name: string, required = false, def?: number) => ({ name, type: 'integer', required, ...(def !== undefined ? { default: def } : {}) }),
  bool: (name: string, required = false, def = false) => ({ name, type: 'boolean', required, default: def }),
  json: (name: string, required = false, def = '{}') => ({ name, type: 'json', required, default: def }),
  float: (name: string, required = false) => ({ name, type: 'number', required }),
};

// Common schema patterns
const timestamps = [
  f.str('created_at', false),
  f.str('updated_at', false),
];

