// ═══════════════════════════════════════════════════════════
// MAIN — drop & recreate all collections
// ═══════════════════════════════════════════════════════════

async function main() {
  console.log('═══════════════════════════════════════════════════════');
  console.log('iSchool — Lightbase Collection Setup');
  console.log('Project:', PROJECT);
  console.log('═══════════════════════════════════════════════════════\n');

  const existing = await listCollections();
  console.log(`Found ${existing.size} existing collections.\n`);

  // Delete and recreate each collection in schema order
  const sortedNames = Object.keys(SCHEMAS).sort();
  let created = 0, kept = 0, failed = 0; // kept = existing, preserved untouched

  for (const name of sortedNames) {
    const fields = SCHEMAS[name];
    // Non-destructive ensure variant (ensure-lightbase-collections.ts):
    // SKIP existing collections (they hold live seeded data) — only create missing ones.
    if (existing.has(name)) {
      kept++;
      continue;
    }
    // Create with new schema
    try {
      await createCollection(name, fields);
      created++;
    } catch (e: any) {
      console.warn(`  [error] ${name}: ${e.message.substring(0, 100)}`);
      failed++;
    }
  }

  console.log(`\nDone. Created ${created} collections, ${failed} failed.`);

  // Verify
  const after = await listCollections();
  console.log(`Total collections now: ${after.size}`);
}

main().catch(e => { console.error('FATAL:', e); process.exit(1); });
